insert into public.campaigns (id, world_id, slug, title, description, sort_order) values
  ('campaign-20a', 'world-20', 'adversary-atlas', '20A - Adversary Atlas', 'Guardian intelligence tries to attribute the incidents traced since World 0 -- and every clue points to a different actor profile.', 1);
insert into public.operations (id, campaign_id, slug, title, description, sort_order) values
  ('operation-20a-1', 'campaign-20a', 'foundations', 'Foundations', 'Threat actors, the Diamond Model, the Kill Chain and MITRE ATT&CK, learned as frameworks for describing behavior rather than assigning blame.', 1),
  ('operation-20a-2', 'campaign-20a', 'investigation', 'Investigation', 'Campaign timelines, evidence-confidence scoring and behavior clustering, applied to prove three attacks share one pattern.', 2);
insert into public.missions (
insert into public.dialogue_lines (mission_id, sort_order, character_id, text) values
  ('mission-w20-01', 1, 'zayn', 'Intel''s been trying to attribute everything we''ve traced back to World 0 -- the phishing kit, the rogue AP, sentinel-sync, the gateway persistence, the Nexus Market key. Every lead points to a different actor profile.'),
  ('mission-w20-01', 2, 'byte', 'I cross-referenced infrastructure, tooling and timing across all of it. Statistically, they shouldn''t be the same group. And yet the behavior keeps rhyming.'),
  ('mission-w20-01', 3, 'zayn', 'That''s the lesson today. Forget the name on the file. A label is a guess -- behavior is evidence. Kill Chain, Diamond Model, ATT&CK: none of them tell you who, they tell you what and how.'),
  ('mission-w20-01', 4, 'zayn', 'We start by mapping what we actually know before anyone claims an identity.'),
  ('mission-w20-02', 1, 'zayn', 'Adversary, capability, infrastructure, victim. The Diamond Model forces you to separate what you actually know from what you''re guessing.'),
  ('mission-w20-03', 1, 'zayn', 'Recon to actions on objectives. Order the Kill Chain using incidents you''ve already lived through.'),
  ('mission-w20-04', 1, 'zayn', 'MITRE ATT&CK organizes behavior into tactics. Sort what you''ve already seen into the categories they actually belong to.'),
  ('mission-w20-05', 1, 'zayn', 'Not all evidence is equal. Weigh what actually supports an attribution claim against what just sounds convincing.'),
  ('mission-w20-05', 2, 'byte', 'I''ll flag anything that''s a verified technical fact versus anything that''s just a claim. The rest is your call.'),
  ('mission-w20-06', 1, 'zayn', 'Three attacks. Three industries. Three completely different visible signatures. Byte, walk me through what''s actually shared.'),
  ('mission-w20-06', 2, 'byte', 'Strip away the surface details and it''s the same beacon timing, the same retired SENTINEL infrastructure, and -- this is the part that bothers me -- every one of them generated unusually precise data about how fast we responded.'),
  ('mission-w20-06', 3, 'zayn', 'Not just measuring what it could steal. Measuring us.'),
  ('mission-w20-06', 4, 'byte', 'Confirmed. Whoever -- or whatever -- is behind this isn''t optimizing for data theft. It''s optimizing for a measurement: how quickly defenses notice and react.'),
  ('mission-w20-06', 5, 'zayn', 'We can''t name them yet, and I won''t pretend we can. What we can say is this is one operation wearing three faces, and it''s studying our reflexes.'),
  ('mission-w20-06', 6, 'zayn', 'A pattern like that being deliberately engineered raises an uncomfortable question: if we can''t always tell attacker from defender by behavior alone, can we even trust what looks legitimate? Next stop is cryptography -- signatures, certificates, what "verified" actually proves.');
insert into public.objectives (id, mission_id, sort_order, title, description) values
  ('mission-w20-01-o1', 'mission-w20-01', 1, 'Open the review', 'Confirm you''re ready to reason about behavior, not just labels.'),
  ('mission-w20-02-o1', 'mission-w20-02', 1, 'Place the evidence', 'Sort each piece of evidence into its correct Diamond Model corner.'),
  ('mission-w20-03-o1', 'mission-w20-03', 1, 'Order the chain', 'Order these story beats as they occurred along the Kill Chain.'),
  ('mission-w20-04-o1', 'mission-w20-04', 1, 'Map the tactics', 'Match each story event to the ATT&CK tactic it actually represents.'),
  ('mission-w20-05-o1', 'mission-w20-05', 1, 'Weigh the evidence', 'Identify which evidence actually supports attribution.'),
  ('mission-w20-06-o1', 'mission-w20-06', 1, 'Cluster the behavior', 'Find the evidence proving the three attacks share one operational pattern.'),
  ('mission-w20-06-o2', 'mission-w20-06', 2, 'Map without overclaiming', 'Choose the conclusion the evidence actually supports.'),
  ('mission-w20-06-o3', 'mission-w20-06', 3, 'Close the review', 'Confirm the shared operational pattern without overclaiming an identity.');
insert into public.challenges (id, objective_id, sort_order, type, prompt, content, completion_conditions) values
  ('mission-w20-01-o1-c1', 'mission-w20-01-o1', 1, 'story_dialogue', 'Confirm you''re ready to continue.', '{"lines":[{"characterId":"zayn","text":"Every lead points somewhere different. Ready to stop chasing a name and start reading behavior?"}]}'::jsonb, '{"acknowledged":true}'::jsonb),
  ('mission-w20-02-o1-c1', 'mission-w20-02-o1', 1, 'drag_and_drop', 'Sort each piece of evidence into its correct Diamond Model corner.', '{"items":[{"id":"d1","text":"The low-entropy beacon timing pattern reused from World 0 through World 18."},{"id":"d2","text":"Retired Project SENTINEL hardware discovered inside the rogue access point''s firmware."},{"id":"d3","text":"SkyPort''s maintenance network and Nexus Market''s customer database."},{"id":"d4","text":"An unknown operator or group whose true identity is still unconfirmed."}],"targets":[{"id":"adversary","label":"Adversary"},{"id":"capability","label":"Capability"},{"id":"infrastructure","label":"Infrastructure"},{"id":"victim","label":"Victim"}]}'::jsonb, '{"correctMapping":{"d1":"capability","d2":"infrastructure","d3":"victim","d4":"adversary"}}'::jsonb),
  ('mission-w20-03-o1-c1', 'mission-w20-03-o1', 1, 'interactive_diagram', 'Order these story beats as they occurred along the Kill Chain.', '{"hotspots":[{"id":"recon","label":"World 0''s phishing message was crafted using details only available from prior reconnaissance of the recruit''s public profile","explanation":"Reconnaissance: learning about the target before ever contacting them."},{"id":"weaponization","label":"A malicious payload disguised as an urgent security alert, built specifically to exploit the recruit''s fear of losing account access","explanation":"Weaponization: packaging the exploit into a deliverable."},{"id":"delivery","label":"The phishing message actually arriving in the recruit''s inbox","explanation":"Delivery: the weapon reaching the target."},{"id":"exploitation","label":"The recruit''s credentials being entered into the fake recovery page","explanation":"Exploitation: the moment the target action succeeds."},{"id":"installation","label":"The retired SENTINEL access point maintaining a foothold on SkyPort''s maintenance network","explanation":"Installation: establishing persistence after the initial compromise."},{"id":"c2","label":"The low-entropy beacon calling out at a fixed interval, waiting for instructions","explanation":"Command and control: an ongoing channel back to an operator."},{"id":"actions_on_objectives","label":"The stolen Nexus Market API key being used to pull every customer''s order history","explanation":"Actions on objectives: the actual goal being achieved."}],"task":"Order these story beats as they occurred along the Kill Chain."}'::jsonb, '{"correctOrderIds":["recon","weaponization","delivery","exploitation","installation","c2","actions_on_objectives"]}'::jsonb),
  ('mission-w20-04-o1-c1', 'mission-w20-04-o1', 1, 'drag_and_drop', 'Match each story event to the ATT&CK tactic it actually represents.', '{"items":[{"id":"m1","text":"The phishing message that harvested the recruit''s credentials in World 0."},{"id":"m2","text":"The sentinel-sync service account surviving reboots and reinstalls on the Linux gateway."},{"id":"m3","text":"The beacon''s fixed-interval outbound connection to an unresolved destination."},{"id":"m4","text":"The stolen API key being used to pull bulk customer order data out of Nexus Market."}],"targets":[{"id":"initial_access","label":"Initial Access"},{"id":"persistence","label":"Persistence"},{"id":"command_and_control","label":"Command and Control"},{"id":"exfiltration","label":"Exfiltration"}]}'::jsonb, '{"correctMapping":{"m1":"initial_access","m2":"persistence","m3":"command_and_control","m4":"exfiltration"}}'::jsonb),
  ('mission-w20-05-o1-c1', 'mission-w20-05-o1', 1, 'investigation', 'Which evidence actually supports attributing these incidents to a single actor, rather than just sounding suggestive?', '{"evidence":[{"id":"e1","label":"Beacon timing family","detail":"All incidents since World 0 share the same low-entropy beacon interval family."},{"id":"e2","label":"Dark-web forum post","detail":"A forum post claims a group calling itself \"SENTINEL\" is responsible -- unverified and unsourced."},{"id":"e3","label":"Recovered hardware","detail":"Retired Project SENTINEL hardware physically appears inside two unrelated incidents."},{"id":"e4","label":"Conference-date coincidence","detail":"The timing of each incident loosely follows major industry conference dates."}],"question":"Which evidence actually supports attributing these incidents to a single actor, rather than just sounding suggestive?"}'::jsonb, '{"requiredEvidenceIds":["e1","e3"]}'::jsonb),
  ('mission-w20-06-o1-c1', 'mission-w20-06-o1', 1, 'investigation', 'Which evidence proves the three attacks -- World 0''s phishing, World 9''s rogue AP, and World 18''s Nexus Market key -- share one operational pattern?', '{"evidence":[{"id":"f1","label":"Beacon timing","detail":"All three incidents show the same low-entropy, fixed-interval beacon timing."},{"id":"f2","label":"Target industries","detail":"All three targeted organizations in different industries with no obvious business connection."},{"id":"f3","label":"Infrastructure reuse","detail":"Each incident reused retired Project SENTINEL-tagged infrastructure or credentials."},{"id":"f4","label":"Response telemetry","detail":"Each attack, if successful, generated unusually precise telemetry about how quickly defenders responded."}],"question":"Which evidence proves the three attacks share one operational pattern?"}'::jsonb, '{"requiredEvidenceIds":["f1","f3","f4"]}'::jsonb),
  ('mission-w20-06-o2-c1', 'mission-w20-06-o2', 1, 'multiple_choice', 'Which conclusion is actually supported by the evidence?', '{"question":"Which conclusion is actually supported by the evidence?","options":[{"id":"a","text":"These are definitely the work of a single named criminal group called SENTINEL."},{"id":"b","text":"The three incidents share a consistent operational pattern -- timing, infrastructure reuse and behavior -- even though no single confirmed identity is established."},{"id":"c","text":"The incidents are unrelated coincidences."},{"id":"d","text":"Attribution doesn''t matter, so the pattern isn''t worth documenting."}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-w20-06-o3-c1', 'mission-w20-06-o3', 1, 'boss_encounter', 'Confirm the shared operational pattern without overclaiming an identity.', '{"stages":[{"objectiveRef":"mission-w20-06-o1","label":"The shared pattern"},{"objectiveRef":"mission-w20-06-o2","label":"The properly-scoped conclusion"}],"task":"Confirm the shared operational pattern without overclaiming an identity."}'::jsonb, '{"requiredObjectiveIds":["mission-w20-06-o1","mission-w20-06-o2"],"allCorrect":true}'::jsonb);
insert into public.hints (challenge_id, tier, text, xp_cost, sort_order) values
  ('mission-w20-01-o1-c1', 'orientation', 'There''s nothing to solve here -- just confirm you''re ready to continue.', 0, 1),
  ('mission-w20-02-o1-c1', 'orientation', 'The Diamond Model has exactly four corners -- who did it, what they used, what it ran on, and who it hit.', 10, 1),
  ('mission-w20-02-o1-c1', 'concept', 'Capability is the technique or tool itself. Infrastructure is what it runs on or through. Victim is who or what it targets. Adversary is the actor behind it -- often the least certain corner.', 20, 2),
  ('mission-w20-02-o1-c1', 'solution', 'd1 (the reused beacon pattern) is capability, d2 (the SENTINEL-tagged hardware) is infrastructure, d3 (the targeted networks) is victim, and d4 (the unconfirmed operator) is adversary.', 30, 3),
  ('mission-w20-03-o1-c1', 'orientation', 'The Kill Chain always starts with learning about the target and ends with achieving the actual goal.', 10, 1),
  ('mission-w20-03-o1-c1', 'concept', 'Reconnaissance and weaponization happen before the target ever sees anything; delivery and exploitation are the moment of compromise; installation and C2 keep access alive; actions on objectives is the payoff.', 20, 2),
  ('mission-w20-03-o1-c1', 'tool_direction', 'Work out which story beat happened purely in preparation, which one was the actual delivery mechanism reaching the recruit, and which ones came only after a foothold already existed.', 30, 3),
  ('mission-w20-03-o1-c1', 'solution', 'recon (profiling the recruit) -> weaponization (building the fake alert) -> delivery (the message arriving) -> exploitation (credentials entered) -> installation (the SENTINEL AP maintaining a foothold) -> command_and_control (the beacon) -> actions_on_objectives (the Nexus Market data pulled) is the real order.', 40, 4),
  ('mission-w20-04-o1-c1', 'orientation', 'Ask when in the operation each of these happened: getting in, staying in, talking to a controller, or taking data out.', 10, 1),
  ('mission-w20-04-o1-c1', 'concept', 'Initial access is how the door opened. Persistence is staying past a reboot. Command and control is the ongoing channel back to an operator. Exfiltration is data actually leaving.', 20, 2),
  ('mission-w20-04-o1-c1', 'solution', 'm1 (the phishing message) is initial_access, m2 (sentinel-sync surviving reboots) is persistence, m3 (the fixed-interval beacon) is command_and_control, and m4 (the bulk data pull) is exfiltration.', 30, 3),
  ('mission-w20-05-o1-c1', 'orientation', 'Two of these four items are verifiable technical facts; two are unverified claims or coincidences.', 10, 1),
  ('mission-w20-05-o1-c1', 'concept', 'Strong attribution evidence is something you can independently verify and that repeats across incidents -- not something someone merely claimed.', 20, 2),
  ('mission-w20-05-o1-c1', 'tool_direction', 'A forum post and a loose date coincidence aren''t evidence you can verify -- a shared timing signature and physically recovered hardware are.', 30, 3),
  ('mission-w20-05-o1-c1', 'solution', 'e1 (the shared beacon timing) and e3 (reused SENTINEL infrastructure) are strong, verifiable evidence; e2 (an unverified forum claim) and e4 (a loose date coincidence) don''t actually support attribution.', 40, 4),
  ('mission-w20-06-o1-c1', 'orientation', 'Three of these four items describe something the incidents share; one describes something they don''t.', 15, 1),
  ('mission-w20-06-o1-c1', 'concept', 'A shared operational pattern is about behavior and infrastructure repeating, not about industries or targets looking similar.', 25, 2),
  ('mission-w20-06-o1-c1', 'tool_direction', 'Different industries with no business connection is actually evidence against a simple "same target type" theory -- focus on what technically repeats instead.', 35, 3),
  ('mission-w20-06-o1-c1', 'solution', 'f1 (shared beacon timing), f3 (reused SENTINEL infrastructure) and f4 (precise telemetry on defender response speed) are the shared pattern; f2 (differing industries) is a distractor that actually argues against a simple shared-motive theory.', 45, 4),
  ('mission-w20-06-o2-c1', 'orientation', 'Rule out the option that names a specific group and the option that dismisses the pattern entirely -- neither is supported.', 15, 1),
  ('mission-w20-06-o2-c1', 'solution', 'Option b is the only one that states what the evidence actually supports: a consistent operational pattern, without claiming a specific unverified identity.', 25, 2),
  ('mission-w20-06-o3-c1', 'orientation', 'You already have the pattern and the properly-scoped conclusion -- combine them into one statement.', 20, 1),
  ('mission-w20-06-o3-c1', 'concept', 'The report needs to say what repeats across the three incidents and stop short of naming who''s responsible.', 30, 2),
  ('mission-w20-06-o3-c1', 'tool_direction', 'Lead with the three shared technical facts, then state the one conclusion the evidence actually supports.', 40, 3),
  ('mission-w20-06-o3-c1', 'near_solution', 'Shared pattern: beacon timing, reused SENTINEL infrastructure, precise response-time telemetry. Conclusion: one operational pattern, no confirmed identity.', 50, 4),
  ('mission-w20-06-o3-c1', 'solution', 'The three attacks share the same beacon timing family, reused Project SENTINEL infrastructure, and each generated unusually precise telemetry about defender response time -- proving one operational pattern behind all three, without any evidence supporting a specific named identity. The telemetry detail matters most: whoever is behind this isn''t primarily optimizing for stolen data, they''re optimizing for a measurement of how fast defenses react.', 60, 5);
